import os
import time
import logging
from six import string_types
from typing import Union, Optional, List
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.ul.stream.aasyslog.utils import (wait_until_method_succeed,
                                          current_datatime,
                                          create_directory_if_not_exist,
                                          verify_local_path_exists_and_is_dir,
                                          verify_remote_paths_exist_and_not_dir,
                                          get_full_destination_paths)
from taf.ul.stream.aasyslog import aasyslog_tput as aasyslog_throughput
from taf.ul.stream.aasyslog.exceptions import NcPidNotFoundException
from taf.ul.stream.aasyslog.aasyslog_throughput_config import AasyslogThroughPutConfiguration


class AasyslogThroughput(object):
    def __init__(self):
        self._configure = None

    def collect_aasyslog_throughput(self,
                                    host: str,
                                    username: str,
                                    password: str,
                                    local_output_dir: str,
                                    ccs_shell_type: Optional[str] = "MCU",
                                    omit: Union[str, int] = 60,
                                    end: Union[str, int] = 660,
                                    stop_after_duration: Optional[bool] = True,
                                    stream_incoming_host: Optional[str] = "127.0.0.1",
                                    remote_log_dir: Optional[str] = "/tmp/",
                                    log_name: Optional[str] = "Aasys_CCS_MCU.txt",
                                    filter: Optional[str] = '') -> str:
        """
        Keep capturing Aasyslog for given duration.
        As the moment traffic just started, throughput will be unstable (Acceptable and should be ignored)
        Add Ignore time before and after throughput capturing.

        :param host: host ip addr
        :param username: username
        :param password: password
        :param ccs_shell_type: two paramater can choose[mcu,rt],
                               the syslog with CCS_MCU contain L2LO and CCS_RT contain L2HI.
        :param omit: sleep time
        :param end: sleep time
        :param stop_after_duration: if teardown after duration
        :param stream_incoming_host: log ip addr
        :param remote_log_dir: gnb path
        :param log_name: log name
        :param filter: the save log can add filter to aviod too large
        :param local_output_dir: local output dir
        """
        omit = int(omit)
        duration = int(end) - omit
        time.sleep(omit)

        self._stop_collecting(host, username, password)
        self._enable_aasyslog_config(host, username, password, ccs_shell_type)
        self._start_collecting(host,
                               username,
                               password,
                               filter,
                               remote_log_dir,
                               log_name,
                               stream_incoming_host,
                               duration)
        time.sleep(duration)
        local_path = os.path.join(local_output_dir, f'{current_datatime()}_{log_name}')
        log_path = os.path.join(remote_log_dir, log_name)
        self.download_aasyslog_file(host=host,
                                    username=username,
                                    password=password,
                                    log_path=log_path,
                                    local_path=local_path)
        if stop_after_duration:
            self._stop_collecting(host, username, password)
        return local_path

    def _stop_collecting(self,
                         host: Optional[str] = None,
                         username: Optional[str] = None,
                         password: Optional[str] = None,
                         ccs_shell_type: Optional[str] = "MCU"):
        """
        Teardown the save Aasyslog progress in gnb.

        :param host: host ip addr
        :param username: username
        :param password: password
        :param connection: str represents ssh connection
        """
        self._setup_ssh_connection(host, username, password)
        self._kill_nc()
        self._teardown_ssh_connection()

        self._configure = AasyslogThroughPutConfiguration(host, username, password, ccs_shell_type)
        response = wait_until_method_succeed(60, 0.5, self._configure.disable)
        return response

    def _kill_nc(self):
        command = "ps -ef | grep 51000| grep -v grep| awk '{print $2}'"
        self._ssh.send_command(command)
        command = "ps -ef |grep nc|grep 51000| grep -v grep | awk '{print $2}'|xargs kill -9"
        self._ssh.send_command(command)
        time.sleep(3)
        command = "ps -ef |grep nc|grep 51000|grep -v grep| awk '{print $2}'"
        nc_pid = self._ssh.execute(command)
        assert nc_pid == ''

    def _enable_aasyslog_config(self,
                                host: str,
                                username: str,
                                password: str,
                                ccs_shell_type: Optional[str] = "MCU"):
        """
        Precondition to config the RD parameter on aisk to make aasyslog output directly.

        :param host: host ip addr
        :param username: username
        :param password: password
        :param ccs_shell_type: two paramater can choose[mcu,rt],
                               the syslog with CCS_MCU contain L2LO and CCS_RT contain L2HI.
        """
        self._configure = AasyslogThroughPutConfiguration(host, username, password, ccs_shell_type)
        response = wait_until_method_succeed(60, 0.5, self._configure.enable)
        return response

    def _start_collecting(self,
                          host: str,
                          username: str,
                          password: str,
                          filter: Optional[str] = '',
                          remote_log_dir: Optional[str] = "/tmp/",
                          log_name: Optional[str] = "Aasys_CCS_MCU.txt",
                          stream_incoming_host: Optional[str] = "127.0.0.1",
                          timeout: Union[str, int] = 900):
        """
        Start and save the Aasyslog in gnb with same checkpoint need check the before syslog.

        :param host: host ip addr
        :param username: username
        :param password: password
        :param filter: the save log can add filter to aviod too large
        :param remote_log_dir: gnb path
        :param log_name: log name
        :param stream_incoming_host: log ip addr
        :param timeout: captrue timeout in backgroud.'s'for seconds,'m' for minutes,'h'for hours or 'd'for days
        :param is_ssh_con_released:
        :param connection: str represents ssh connection
        :param duration: sleep time
        """
        if isinstance(timeout, str) and "m" in timeout:
            timeout = int(timeout.rstrip('m')) * 60

        self._setup_ssh_connection(host, username, password)
        command = f"rm - rf {remote_log_dir}{log_name}"
        self._ssh.send_command(command)

        time.sleep(3)

        gnb_log_path = os.path.join(remote_log_dir, log_name)

        status = None
        for _ in range(3):
            self._start_nc(gnb_log_path, timeout, stream_incoming_host, filter)
            status = wait_until_method_succeed(5, 1, self._verify_aasyslog_process_is_started, False)
            if status is not None:
                break
        assert status is True

        self._teardown_ssh_connection()
        return gnb_log_path

    def _start_nc(self,
                  gnb_log_path: str,
                  timeout: Union[str, int] = 900,
                  stream_incoming_host: Optional[str] = "127.0.0.1",
                  filter: Optional[str] = ''):
        command = (f'timeout {timeout} nc -u -w 100 -l {stream_incoming_host} 51000 | '
                   f'grep -a "{filter}">{gnb_log_path} &')
        self._ssh.send_command(command)

    def _verify_aasyslog_process_is_started(self):
        nc_pid = self._retrieve_nc_pid()
        if nc_pid:
            return True
        raise NcPidNotFoundException(f'{nc_pid} is empty')

    def _retrieve_nc_pid(self):
        command = "ps -ef|grep nc | grep 51000 | grep -v grep | tail -n 1|awk '{print $2}'"
        return self._ssh.execute(command)

    def download_aasyslog_file(self,
                               host: str,
                               username: str,
                               password: str,
                               log_path: str,
                               local_path: str):
        self._setup_ssh_connection(host, username, password)
        self._download_file(remote_path=log_path, local_path=local_path)
        self._teardown_ssh_connection()

    def check_aasyslog_throughput(self,
                                  direction: str,
                                  log_path: str,
                                  local_output_dir: str,
                                  cells: List[Union[str, int]],
                                  theoretical_throughput: str,
                                  average_tolerance: Union[float, int] = 0.95,
                                  minimum_tolerance: Union[float, int] = 0.85,
                                  ca: Optional[bool] = False,
                                  enable_chart_generation: Optional[bool] = True,
                                  customized_chart_file_name: Optional[str] = '') -> str:
        """
        Check aasyslog throughput

        :param direction: DL or UL
        :param log_path: path for log which restore aasyslog
        :param local_output_dir: path for log output
        :param cells: cells list
        :param theoretical_throughput: theoretical throughput
        :param average_tolerance: average tolerance
        :param minimum_tolerance: minimum tolerance
        :param ca: with ca or not
        :param customized_chart_file_name: customized log namen
        :param enable_chart_generation: generate image or not
        """
        create_directory_if_not_exist(local_output_dir)
        raw_throughput, records = aasyslog_throughput.get_aasyslog_throughput(direction, log_path, cells, ca)
        aasyslog_throughput.check_aasyslog_throughput(
            raw_throughput=raw_throughput,
            records=records,
            direction=direction,
            cells=cells,
            theoretical_throughput=theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            ca=ca,
            output_dir=local_output_dir,
            customized_chart_file_name=customized_chart_file_name,
            enable_chart_generation=enable_chart_generation
        )
        return raw_throughput

    def check_bi_aasyslog_throughput(self,
                                     log_path: str,
                                     local_output_dir: str,
                                     cells: List,
                                     ul_theoretical_throughput: str,
                                     dl_theoretical_throughput: str,
                                     average_tolerance: Union[float, int] = 0.95,
                                     minimum_tolerance: Union[float, int] = 0.85,
                                     ca: Optional[bool] = False,
                                     customized_chart_file_name: Optional[str] = '',
                                     enable_chart_generation: Optional[bool] = True):
        """
        Check bi aasyslog throughput

        :param log_path: path for log which restore aasyslog
        :param local_output_dir: path for log output
        :param cells: cells list
        :param ul_theoretical_throughput: ul theoretical throughput
        :param dl_theoretical_throughput: dl theoretical throughput
        :param average_tolerance: average tolerance
        :param minimum_tolerance: minimum tolerance
        :param ca: with ca or not
        :param customized_chart_file_name: customized log namen
        :param enable_chart_generation: generate image or not
        """
        create_directory_if_not_exist(local_output_dir)
        ul_tput_result, _ = aasyslog_throughput.get_aasyslog_throughput(direction="ul", log_path=log_path, cells=cells,
                                                                        ca=ca)
        dl_tput_result, _ = aasyslog_throughput.get_aasyslog_throughput(direction="dl", log_path=log_path, cells=cells,
                                                                        ca=ca)
        aasyslog_throughput.check_bi_aasyslog_throughput(
            log_path=log_path,
            cells=cells,
            ul_theoretical_throughput=ul_theoretical_throughput,
            dl_theoretical_throughput=dl_theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            ca=ca,
            output_dir=local_output_dir,
            customized_chart_file_name=customized_chart_file_name,
            enable_chart_generation=enable_chart_generation
        )
        return ul_tput_result, dl_tput_result

    def _setup_ssh_connection(self, host: str, username: str, password: str):
        self._managed_ssh_connection = ManagedSshConnection(host=host, user=username, password=password)
        self._managed_ssh_connection.setup()
        self._ssh = self._managed_ssh_connection.ssh_connection

    def _teardown_ssh_connection(self):
        self._managed_ssh_connection.teardown()

    def _download_file(self, remote_path: str, local_path: str, timeout: Optional[int] = 30):
        fp = self._ssh.files
        single_path = isinstance(remote_path, string_types)
        if single_path:
            remote_path = [remote_path]
            full_local_paths = [local_path]
        else:
            verify_local_path_exists_and_is_dir(local_path)
            verify_remote_paths_exist_and_not_dir(remote_path, fp, timeout)

            full_local_paths = get_full_destination_paths(remote_path, local_path)

        logging.info(f"Downloading file(s) from {self._ssh.address}")
        for remote, local in zip(remote_path, full_local_paths):
            logging.info(f"Downloading remote file {remote} into local path {local}")
            fp.get(remote, local, timeout)
